#!/usr/bin/env node
// Fetch nomenclatural topology (accepted name, basionym, infraspecific variations,
// full name history) from Index Fungorum ("Species Fungorum") via ChecklistBank for
// each species and emit typed TS modules under src/data/taxonomy/species.
// Generated files are not meant to be edited by hand; snapshots are committed.
import { promises as fs, existsSync, readdirSync } from 'fs'
import path from 'path'
import { format } from 'prettier'
import {
  ROOT,
  searchNameUsages,
  getName,
  getNameUsage,
  getNameRelations,
  getTreeChildren,
  getSynonyms,
  getReference,
  sleep,
} from './lib/col.mjs'
import { DEFAULT_COL_DATASET_KEY } from './config/col.mjs'

const SPECIES_DIR = path.join(ROOT, 'src', 'content', 'species')
const OUT_DIR = path.join(ROOT, 'src', 'data', 'taxonomy', 'species')
const WD_SPECIES_DIR = path.join(ROOT, 'src', 'data', 'wikidata', 'species')
const FORCE = process.argv.includes('--force')

const j = JSON.stringify
const PRETTIER = { parser: 'typescript', semi: false, singleQuote: true, printWidth: 100 }

// QID -> Wikidata taxon name (P225). Read textually rather than imported: the
// barrel's extensionless relative imports are not resolvable by Node's ESM loader.
async function loadTaxonNames() {
  const map = new Map()
  if (!existsSync(WD_SPECIES_DIR)) return map
  for (const file of readdirSync(WD_SPECIES_DIR)) {
    const m = file.match(/^(Q\d+)\.ts$/)
    if (!m) continue
    const src = await fs.readFile(path.join(WD_SPECIES_DIR, file), 'utf8')
    const t = src.match(/taxonName:\s*(['"])([^'"]*)\1/)
    if (t) map.set(m[1], t[2])
  }
  return map
}

function isInfraspecific(rank) {
  if (!rank) return false
  const r = String(rank).toLowerCase().trim()
  if (r === 'species' || r === 'genus') return false
  return /(variety|subspecies|subsp\.|forma|form|f\.|lusus|proles|var\.)/.test(r)
}

function formatUsage(u, overrides = {}) {
  if (!u) return null
  const nested = u.name && typeof u.name === 'object' ? u.name : null
  const scientificName =
    nested?.scientificName ?? (typeof u.name === 'string' ? u.name : u.scientificName)
  if (!scientificName) return null
  const out = {
    scientificName,
    authorship: nested?.authorship ?? u.authorship ?? undefined,
    rank: nested?.rank ?? u.rank ?? undefined,
    usageId: u.id ?? nested?.id ?? undefined,
    status: u.status ?? undefined,
    parentUsageId: u.parentId ?? undefined,
    ...overrides,
  }
  for (const k of Object.keys(out)) if (out[k] === undefined) delete out[k]
  return out
}

function publishedInIdOf(u) {
  if (!u) return undefined
  const nested = u.name && typeof u.name === 'object' ? u.name : null
  return nested?.publishedInId ?? u.publishedInId
}

function makeYearAttacher(datasetKey, refCache, log) {
  return async function attachYear(entry, refId) {
    if (!entry || !refId) return
    if (refCache.has(refId)) {
      const y = refCache.get(refId)
      if (y) entry.year = y
      return
    }
    let year = null
    try {
      const ref = await getReference(datasetKey, refId, { log })
      year = ref.year ?? ref.csl?.issued?.['date-parts']?.[0]?.[0] ?? null
    } catch (e) {
      log(`  reference ${refId} failed: ${e.message}`)
    }
    refCache.set(refId, year)
    if (year) entry.year = year
    await sleep(40)
  }
}

function pickCandidate(exact, expectedName, log, slug) {
  if (exact.length === 0) return null
  if (exact.length === 1) return exact[0]
  const accepted = exact.filter((r) => r.status === 'accepted')
  const pool = accepted.length ? accepted : exact
  if (expectedName) {
    const exp = expectedName.toLowerCase()
    const matching = pool.filter((r) => {
      const resolved = r.accepted ?? r
      const n = resolved.name && typeof resolved.name === 'object' ? resolved.name : resolved
      return n.scientificName?.toLowerCase() === exp
    })
    if (matching.length >= 1) {
      if (matching.length > 1)
        log(`[col] ${slug}: still ambiguous after cross-check (${matching.length} candidates)`)
      return matching[0]
    }
    log(
      `[col] ${slug}: ambiguous and no candidate resolves to "${expectedName}" -- manual review needed`,
    )
  } else {
    log(`[col] ${slug}: ambiguous (${exact.length} exact matches); picking first`)
  }
  return pool[0]
}

function renderTaxonomyTs(slug, data) {
  const lines = []
  lines.push(`// Taxonomy topology for ${slug}`)
  lines.push('// Generated by scripts/update-species-taxonomy.mjs -- do not edit by hand.')
  lines.push("import type { TaxonomyData } from '../types'")
  lines.push('')
  lines.push('export const taxonomy: TaxonomyData = {')
  lines.push(`  colDatasetKey: ${j(data.colDatasetKey)},`)
  lines.push(`  colUsageId: ${j(data.colUsageId)},`)
  lines.push(`  accepted: ${j(data.accepted)},`)
  lines.push(`  basionym: ${data.basionym ? j(data.basionym) : 'null'},`)
  lines.push(`  variations: ${j(data.variations)},`)
  lines.push(`  fullHistory: ${j(data.fullHistory)},`)
  lines.push(`  lastUpdated: ${j(data.lastUpdated)},`)
  lines.push('}')
  lines.push('')
  lines.push('export default taxonomy')
  return lines.join('\n') + '\n'
}

function renderIndex(manifest) {
  const sorted = manifest.slice().sort((a, b) => a.slug.localeCompare(b.slug))
  const imports = sorted.map(
    (m) => `import { taxonomy as ${m.slug.replace(/-/g, '_')}Taxonomy } from './${m.slug}'`,
  )
  const entries = sorted.map((m) => `  '${m.slug}': ${m.slug.replace(/-/g, '_')}Taxonomy,`)
  return [
    '// Generated by scripts/update-species-taxonomy.mjs -- do not edit by hand.',
    "export type * from '../types'",
    '',
    ...imports,
    '',
    'export const speciesTaxonomy: Record<string, import("../types").TaxonomyData> = {',
    ...entries,
    '}',
    '',
  ].join('\n')
}

async function main() {
  const log = console.log
  const datasetKey = DEFAULT_COL_DATASET_KEY
  if (!datasetKey) throw new Error('No COL dataset key configured')

  await fs.mkdir(OUT_DIR, { recursive: true })
  log(`[col] using datasetKey ${datasetKey}`)

  const species = []
  for (const slug of readdirSync(SPECIES_DIR).sort()) {
    const file = path.join(SPECIES_DIR, slug, 'index.json')
    if (!existsSync(file)) continue
    const doc = JSON.parse(await fs.readFile(file, 'utf8'))
    if (!doc.scientificName) continue
    species.push({ slug, scientificName: doc.scientificName, wikidataId: doc.wikidataId })
  }
  log(`[col] processing ${species.length} species`)

  const manifest = []
  const skipped = []
  const refCache = new Map()
  const attachYear = makeYearAttacher(datasetKey, refCache, log)
  const taxonNames = await loadTaxonNames()

  for (let i = 0; i < species.length; i++) {
    const { slug, scientificName, wikidataId } = species[i]
    try {
      const wdTaxonName = wikidataId ? taxonNames.get(wikidataId) : undefined
      const expected = wdTaxonName || scientificName

      const results = await searchNameUsages(datasetKey, scientificName, { limit: 30, log })
      const exact = results.filter((r) => {
        const n = typeof r.name === 'object' ? r.name?.scientificName : undefined
        const name = r.scientificName ?? n
        return name && name.toLowerCase() === scientificName.toLowerCase()
      })
      const chosen = pickCandidate(exact, expected, log, slug)
      if (!chosen) {
        skipped.push(slug)
        log(`[col] ${i + 1}/${species.length} ${slug}: not found in COL, skipped`)
        await sleep(150)
        continue
      }

      const acceptedUsage = chosen.accepted ?? chosen
      if (acceptedUsage.status && acceptedUsage.status !== 'accepted') {
        log(
          `[col] ${slug}: resolved usage status is "${acceptedUsage.status}" -- manual review needed`,
        )
      }
      const acceptedEntry = formatUsage(acceptedUsage)
      await attachYear(acceptedEntry, publishedInIdOf(acceptedUsage))
      const acceptedNameId = acceptedUsage.name?.id ?? acceptedUsage.id

      let basionymEntry = null
      const relations = await getNameRelations(datasetKey, acceptedNameId, { log })
      const basionymRel = relations.find((r) => String(r.type).toLowerCase() === 'basionym')
      if (basionymRel?.relatedNameId) {
        try {
          let bRecord
          try {
            bRecord = await getNameUsage(datasetKey, basionymRel.relatedNameId, { log })
          } catch {
            bRecord = await getName(datasetKey, basionymRel.relatedNameId, { log })
          }
          basionymEntry = formatUsage(bRecord)
          await attachYear(basionymEntry, publishedInIdOf(bRecord))
        } catch (e) {
          log(`  basionym fetch failed: ${e.message}`)
        }
      }

      const children = await getTreeChildren(datasetKey, acceptedUsage.id, { log })
      const variations = []
      for (const child of children) {
        if (!isInfraspecific(child.rank)) continue
        try {
          const full = await getNameUsage(datasetKey, child.id, { log })
          const entry = formatUsage(full, {
            parentUsageId: child.parentId ?? full.parentId ?? acceptedUsage.id,
          })
          await attachYear(entry, publishedInIdOf(full))
          if (entry) variations.push(entry)
        } catch (e) {
          log(`  variation ${child.id} failed: ${e.message}`)
        }
      }

      const syn = await getSynonyms(datasetKey, acceptedUsage.id, { log })
      const synonymEntries = []
      for (const s of [...syn.homotypic, ...syn.heterotypic]) {
        const e = formatUsage(s)
        if (!e) continue
        synonymEntries.push(e)
        await attachYear(e, publishedInIdOf(s))
      }

      const fullHistory = []
      const seen = new Set()
      const push = (e) => {
        if (!e) return
        if (e.usageId != null) {
          if (seen.has(e.usageId)) return
          seen.add(e.usageId)
        }
        fullHistory.push(e)
      }
      push(basionymEntry)
      push(acceptedEntry)
      for (const v of variations) push(v)
      for (const e of synonymEntries) push(e)

      const taxonomyData = {
        colDatasetKey: datasetKey,
        colUsageId: acceptedUsage.id,
        accepted: acceptedEntry,
        basionym: basionymEntry,
        variations,
        fullHistory,
        lastUpdated: new Date().toISOString().slice(0, 10),
      }

      const ts = await format(renderTaxonomyTs(slug, taxonomyData), PRETTIER)
      const outFile = path.join(OUT_DIR, `${slug}.ts`)
      if (FORCE || !existsSync(outFile) || (await fs.readFile(outFile, 'utf8')) !== ts) {
        await fs.writeFile(outFile, ts)
      }
      manifest.push({ slug })
      log(
        `[col] ${i + 1}/${species.length} ${slug}: ${acceptedEntry.scientificName}` +
          ` -- ${basionymEntry ? 'basionym' : 'no basionym'}, ` +
          `${variations.length} variations, ${fullHistory.length} history entries`,
      )
    } catch (e) {
      log(`[col] ${i + 1}/${species.length} ${slug}: error: ${e.message}`)
      skipped.push(slug)
    }
    if (i < species.length - 1) await sleep(150)
  }

  const idx = await format(renderIndex(manifest), PRETTIER)
  await fs.writeFile(path.join(OUT_DIR, 'index.ts'), idx)

  log(`[col] wrote ${manifest.length} taxonomy files, skipped ${skipped.length}`)
  if (skipped.length) log(`[col] skipped: ${skipped.join(', ')}`)
}

main().catch((err) => {
  console.error('[col] failed:', err)
  process.exit(1)
})
